import sys, time; sys.path.insert(0, "scripts")
import pandas as pd, numpy as np
pd.set_option("display.width", 200); pd.set_option("display.max_columns", 30)
import awareness_analytics as aa
t0=time.time(); D = aa.load_data("data"); print("load", round(time.time()-t0,1))
ph, tr = D["phishing"], D["training"]
m = aa.monthly_rates(ph); print(m[["month","users","delivered","click_rate","click_rate_low","click_rate_high","report_rate","median_minutes_to_report","median_low","median_high"]].round(3).to_string())
k = aa.quarter_kpis(ph, tr); print(aa.kpis_to_frame(k).round(3).to_string())
t0=time.time(); fitted = aa.fit_adjustment_model(ph, "clicked"); adj, res = aa.adjusted_group_rates(ph, "department", fitted=fitted); print("adj dept", round(time.time()-t0,1))
print(adj[["department","users","mean_difficulty","raw_rate","adjusted_rate","adjusted_low","adjusted_high","rank_change","suppressed"]].round(3).to_string())
print(aa.odds_ratio_table(res, "difficulty").round(3).to_string())
t0=time.time(); adjr, _ = aa.adjusted_group_rates(ph, "role_label", fitted=fitted); print("adj role", round(time.time()-t0,1)); print(adjr[["role_label","users","raw_rate","adjusted_rate"]].round(3).to_string())
print(aa.difficulty_curve(ph)[["difficulty","delivered","click_rate","report_rate"]].round(3).to_string())
rc = aa.repeat_clickers(ph); print(rc.to_string())
coh = aa.repeat_clicker_cohort_rates(ph); print(coh[["month","cohort","users","click_rate","report_rate"]].round(3).head(8).to_string())
t0=time.time(); ba = aa.before_after(ph); print("before_after", round(time.time()-t0,1)); print(ba.round(3).to_string())
t0=time.time(); did = aa.training_did(ph, tr); print("did", round(time.time()-t0,1)); print(did["effects"].round(3).to_string()); print(did["cells"].round(3).to_string()); print(did["status_counts"]); print("excluded late", did["excluded_late"])
print(aa.monthly_by_training_status(ph, tr)[["month","status","users","click_rate"]].round(3).head(6).to_string())
print(aa.training_completion_summary(tr, D["people"]).round(3).head(14).to_string())
print(aa.training_completion_curve(tr).tail(3))
print(aa.newsletter_rates(D["newsletter"])[["month","issue_title","special_issue","open_rate","click_rate"]].round(3).to_string())
print(aa.event_summary(D["attendance"], D["events"]).to_string())
print(aa.event_attendee_effect(ph, D["attendance"])[["group","users","report_rate","click_rate"]].round(3).to_string())
g = aa.group_rates(ph, ["department","role_label"], months=aa.POST_MONTHS); print(g[["department","role_label","users","report_rate","suppressed"]].round(3).to_string())
print(aa.describe_change(0.35, 0.17, True, "Report rate"), "|", aa.describe_change(0.07,0.13,False,"Click rate"))
